args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?father ?fatherLabel ?grandmotherIRI ?grandmotherLabel ?grandmotherLiteral WHERE {
  dbr:Edward_Harley,_4th_Earl_of_Oxford_and_Earl_Mortimer dbo:parent ?father .
  OPTIONAL {
    ?father dbo:parent ?grandmotherIRI .
    OPTIONAL { ?grandmotherIRI rdfs:label ?grandmotherLabel FILTER(lang(?grandmotherLabel)='en') }
  }
  OPTIONAL {
    ?father dbp:parents ?grandmotherLiteral . FILTER(isLiteral(?grandmotherLiteral))
  }
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER(lang(?fatherLabel)='en') }
}

